#!/usr/bin/env bash
# generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
#
# Build and deploy the app into a Nextcloud running in a Docker container.
# Designed for Nextcloud AIO, but works for any container that has `occ`.
#
# Usage:
#   bash scripts/deploy-to-remote.sh user@host [options]
#
# Examples:
#   bash scripts/deploy-to-remote.sh alwyzon@borger.co.at --sudo
#   bash scripts/deploy-to-remote.sh alwyzon@borger.co.at --sudo --uninstall
#   bash scripts/deploy-to-remote.sh admin@cloud.example --container nextcloud \
#       --app-dir /var/www/html/custom_apps/upm
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
TARBALL="$PROJECT_ROOT/tmp/upm-deploy.tar.gz"

HOST=""
CONTAINER="nextcloud-aio-nextcloud"
APP_DIR="/var/www/html/custom_apps/upm"
WEB_USER="www-data"
REMOTE_TMP="/tmp/upm-deploy"
USE_SUDO=0
DO_BUILD=1
DO_ENABLE=1
UNINSTALL=0

usage() {
	cat <<'EOF'
Build and deploy UPM into a Nextcloud Docker container.

Usage:
  bash scripts/deploy-to-remote.sh user@host [options]

Options:
  --container NAME   Nextcloud container (default: nextcloud-aio-nextcloud)
  --app-dir PATH     App dir inside the container
                     (default: /var/www/html/custom_apps/upm)
  --web-user USER    Owner of the app files (default: www-data)
  --remote-tmp DIR   Staging dir on the server (default: /tmp/upm-deploy)
  --sudo             Prefix docker with `sudo -n` (AIO installs usually need it)
  --no-build         Skip the frontend build; use the existing js/upm.js
  --no-enable        Copy the files but do not run occ app:enable
  --uninstall        Disable and remove the app (user .db files are untouched)
  -h, --help         Show this help

The remote user needs SSH access and permission to run docker (or sudo for it).
EOF
}

die() { echo "error: $*" >&2; exit 1; }

while [ $# -gt 0 ]; do
	case "$1" in
		--container) [ $# -ge 2 ] || die "--container needs a value"; CONTAINER="$2"; shift 2 ;;
		--app-dir) [ $# -ge 2 ] || die "--app-dir needs a value"; APP_DIR="$2"; shift 2 ;;
		--web-user) [ $# -ge 2 ] || die "--web-user needs a value"; WEB_USER="$2"; shift 2 ;;
		--remote-tmp) [ $# -ge 2 ] || die "--remote-tmp needs a value"; REMOTE_TMP="$2"; shift 2 ;;
		--sudo) USE_SUDO=1; shift ;;
		--no-build) DO_BUILD=0; shift ;;
		--no-enable) DO_ENABLE=0; shift ;;
		--uninstall) UNINSTALL=1; shift ;;
		-h|--help) usage; exit 0 ;;
		-*) die "unknown option: $1 (try --help)" ;;
		*)
			[ -z "$HOST" ] || die "only one user@host may be given"
			HOST="$1"
			shift
			;;
	esac
done

[ -n "$HOST" ] || { usage >&2; exit 1; }
command -v ssh >/dev/null 2>&1 || die "ssh not found"

if [ "$UNINSTALL" -eq 1 ]; then
	echo "==> Uninstalling from $CONTAINER:$APP_DIR"
	scp_required=0
else
	scp_required=1
fi

if [ "$scp_required" -eq 1 ]; then
	command -v scp >/dev/null 2>&1 || die "scp not found"

	if [ "$DO_BUILD" -eq 1 ]; then
		bash "$PROJECT_ROOT/scripts/build-frontend.sh"
	fi

	echo "==> Packaging"
	rm -f "$TARBALL"
	bash "$PROJECT_ROOT/scripts/package-app.sh" "$TARBALL" >/dev/null
	[ -f "$TARBALL" ] || die "packaging failed"

	echo "==> Uploading to $HOST:$REMOTE_TMP"
	ssh "$HOST" "mkdir -p '$REMOTE_TMP'"
	scp -q "$TARBALL" "$HOST:$REMOTE_TMP/upm.tar.gz"
fi

echo "==> Updating $CONTAINER:$APP_DIR"
ssh "$HOST" bash -s -- \
	"$CONTAINER" "$APP_DIR" "$WEB_USER" "$REMOTE_TMP/upm.tar.gz" "$USE_SUDO" "$DO_ENABLE" "$UNINSTALL" <<'REMOTE'
set -euo pipefail

CONTAINER="$1"
APP_DIR="$2"
WEB_USER="$3"
TARBALL="$4"
USE_SUDO="$5"
DO_ENABLE="$6"
UNINSTALL="$7"

if [ "$USE_SUDO" = "1" ]; then
	SUDO=(sudo -n)
else
	SUDO=()
fi
DOCKER=("${SUDO[@]}" docker)

if [ "$UNINSTALL" = "1" ]; then
	"${DOCKER[@]}" exec -u "$WEB_USER" "$CONTAINER" php occ app:disable upm || true
	"${DOCKER[@]}" exec "$CONTAINER" rm -rf "$APP_DIR"
	if "${DOCKER[@]}" exec -u "$WEB_USER" "$CONTAINER" php occ app:list --enabled | grep -q upm; then
		echo "error: upm is still enabled" >&2
		exit 1
	fi
	echo "Uninstalled upm (user .db files were left untouched)."
	exit 0
fi

STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT
tar -xzf "$TARBALL" -C "$STAGE"
[ -f "$STAGE/upm/appinfo/info.xml" ] || { echo "error: bad tarball" >&2; exit 1; }

# Replace the app atomically-ish: stage inside the container, then swap.
"${DOCKER[@]}" exec "$CONTAINER" rm -rf /tmp/upm-deploy
"${DOCKER[@]}" cp "$STAGE/upm" "$CONTAINER:/tmp/upm-deploy"
"${DOCKER[@]}" exec "$CONTAINER" rm -rf "$APP_DIR"
"${DOCKER[@]}" exec "$CONTAINER" mv /tmp/upm-deploy "$APP_DIR"
"${DOCKER[@]}" exec "$CONTAINER" chown -R "$WEB_USER:$WEB_USER" "$APP_DIR"

if [ "$DO_ENABLE" = "1" ]; then
	"${DOCKER[@]}" exec -u "$WEB_USER" "$CONTAINER" php occ app:enable upm
	"${DOCKER[@]}" exec -u "$WEB_USER" "$CONTAINER" php occ app:list --enabled | grep -q upm ||
		{ echo "error: upm is not listed after enabling" >&2; exit 1; }
fi

URL="$("${DOCKER[@]}" exec -u "$WEB_USER" "$CONTAINER" php occ config:system:get overwrite.cli.url 2>/dev/null || true)"
if [ -n "$URL" ]; then
	echo "Installed: ${URL%/}/index.php/apps/upm/"
else
	echo "Installed (open /index.php/apps/upm/ on your instance)."
fi
REMOTE

echo "Done."
